// Per-request correlation ID (Architecture §46). Always generated by the
// server (incoming IDs are not trusted), returned as X-Request-ID and used
// in server-side error logs so a reported problem can be found in the logs.
import { randomUUID } from 'node:crypto'
import type { RequestHandler } from 'express'

declare module 'express-serve-static-core' {
  interface Request {
    requestId: string
  }
}

export const REQUEST_ID_HEADER = 'X-Request-ID'

export const requestId: RequestHandler = (req, res, next) => {
  req.requestId = randomUUID()
  res.set(REQUEST_ID_HEADER, req.requestId)
  next()
}
